window.addEventListener('keydown',e=>{if(e.target?.matches?.('input,select,textarea'))return;if(screen==='embedded')return;if(['story','question','epilogue','exchange'].includes(screen)){journeyKey(e);return;}if(screen==='camp'||screen==='shop'||screen==='platform'){if(e.key==='Escape'){e.preventDefault();setScreen('map')}return}if(screen==='fog'){if(e.key==='Escape'){e.preventDefault();setScreen('map')}return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter','Escape','r','R'].includes(e.key)||loading)return;e.preventDefault();if(screen==='title'){if(e.key==='Enter')startJourney()}else if(screen==='hero'){if(e.key==='ArrowLeft')changeHero(-1);if(e.key==='ArrowRight')changeHero(1);if(e.key.toLowerCase()==='r'){hero=(hero+1+Math.floor(Math.random()*2))%3;render()}if(e.key==='Enter'){if(journeyStarted)showNode('intro5');else setScreen('map')};if(e.key==='Escape')setScreen('title')}else{if(e.key==='Escape'){if(dialog){dialog=false;render()}else setScreen('hero')}else if(e.key==='Enter'){if(dialog){if(mapChoice){dialog=false;render()}else travel();}else{selectDestination(selected)}}else if(dialog&&e.key.startsWith('Arrow')){mapChoice=1-mapChoice;render()}else if(!dialog&&e.key.startsWith('Arrow')){selected=(selected+(['ArrowLeft','ArrowUp'].includes(e.key)?4:1))%5;revealPoint();render()}}});
let displayScale=2,displayDensityQuery=null;
function snapGameToScreen(){const frame=document.querySelector('#frame'),density=window.devicePixelRatio||1;frame.style.transform='none';frame.style.left='0px';frame.style.top='0px';const bounds=frame.getBoundingClientRect();frame.style.left=((Math.round(bounds.left*density)-bounds.left*density)/density)+'px';frame.style.top=((Math.round(bounds.top*density)-bounds.top*density)/density)+'px';}
function applyDisplayScale(){const density=window.devicePixelRatio||1,frame=document.querySelector('#frame');frame.style.setProperty('--game-pixel',(Math.round(displayScale*density)/density)+'px');frame.style.width=(320*Math.round(displayScale*density)/density)+'px';frame.style.height=(240*Math.round(displayScale*density)/density)+'px';document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===displayScale)));requestAnimationFrame(snapGameToScreen)}
function watchDisplayDensity(){if(displayDensityQuery)displayDensityQuery.removeEventListener('change',onDisplayDensityChange);displayDensityQuery=window.matchMedia('(resolution: '+(window.devicePixelRatio||1)+'dppx)');displayDensityQuery.addEventListener('change',onDisplayDensityChange)}
function onDisplayDensityChange(){applyDisplayScale();watchDisplayDensity()}
document.querySelectorAll('[data-scale]').forEach(b=>b.onclick=()=>{displayScale=Number(b.dataset.scale);applyDisplayScale()});
window.addEventListener('resize',applyDisplayScale);applyDisplayScale();watchDisplayDensity();
let drag=null;
function mapPointer(e){const bounds=controls.getBoundingClientRect();return {x:(e.clientX-bounds.left)*320/bounds.width,y:(e.clientY-bounds.top)*240/bounds.height}}
controls.addEventListener('pointerdown',e=>{if(screen!=='map'||dialog||loading||e.button!==0)return;const p=mapPointer(e);if(p.x<mapView.x||p.x>=mapView.x+mapView.w||p.y<mapView.y||p.y>=mapView.y+mapView.h)return;drag={id:e.pointerId,startX:p.x,startY:p.y,camX:camera.x,camY:camera.y,x:p.x,y:p.y,moved:false};controls.setPointerCapture(e.pointerId);e.preventDefault()});
controls.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=mapPointer(e);if(Math.hypot(p.x-drag.startX,p.y-drag.startY)>2)drag.moved=true;if(drag.moved){camera.x=drag.camX-(p.x-drag.startX);camera.y=drag.camY-(p.y-drag.startY);clampCamera();controls.classList.add('dragging');render()}drag.x=p.x;drag.y=p.y});
controls.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const p=mapPointer(e),wasDrag=drag.moved;drag=null;controls.classList.remove('dragging');if(controls.hasPointerCapture(e.pointerId))controls.releasePointerCapture(e.pointerId);if(!wasDrag){const found=buttons.find(b=>b.mapPoint&&p.x>=b.x&&p.x<b.x+b.w&&p.y>=b.y&&p.y<b.y+b.h);if(found)found.fn()}e.preventDefault()});
controls.addEventListener('pointercancel',()=>{drag=null;controls.classList.remove('dragging')});
