for(const k of ['intro2','intro3','intro4','reward_fish','reward_niva','reward_room','reward_map']){names.push(k);assetFiles[k]=k;}
function stopGames(){fogGame?.stop();campGame?.stop();shopGame?.stop();platformGame?.stop();}
function startJourney(){stopGames();clearInterval(timer);loading=false;visited.clear();for(const k in rewards)delete rewards[k];travelItems.clear();journeyStarted=true;journeyActive=true;nextChapter=0;cash=260;selected=0;showNode('intro2');}
function selectDestination(i){selected=i;dialog=true;mapChoice=0;announce('Вы хотите отправиться '+points[i].destination+'?');render();}
function beginChapter(i){journeyActive=true;selected=i;const id='entry'+i;journeyNodes[id]={type:'question',body:chapterQuestions[i],next:(i+1)+'.1',no:i===3?'4.1':'map'};showNode(id);}
function showNode(id){clearTimeout(storyTimer);storyTimer=null;stopGames();if(id==='hero'){setScreen('hero');return;}if(id==='map'){journeyActive=false;selected=nextChapter;revealPoint();setScreen('map');return;}if(id==='title'){journeyActive=false;journeyStarted=false;setScreen('title');return;}journeyNode=id;journeyChoice=0;const n=journeyNodes[id];if(!n)throw Error('Unknown journey node: '+id);if(n.reward&&!rewards[id]){rewards[id]={name:n.reward,value:10};if(n.item)travelItems.add(n.item);}if(n.chapter!==undefined){visited.add(n.chapter);nextChapter=Math.min(4,n.chapter+1);}if(n.type==='game'){if(['sredny','fog','home'].includes(n.game))launchFogRace(n.game);else if(['coast','bear','house','village'].includes(n.game))launchCampSearch(n.game);else if(n.game==='shop'){cash=7260;launchTeriberkaShop();}else if(n.game==='platform')launchPlatform();else if(n.game==='exchange')launchExchange();return;}setScreen(n.type==='question'?'question':n.type==='epilogue'?'epilogue':'story');announce(n.body);if(id==='intro5'&&n.hold)storyTimer=setTimeout(()=>{if(journeyNode===id&&screen==='story')advanceStory();},n.hold);}
function gameCompleted(){if(journeyActive)showNode(journeyNodes[journeyNode].next);}
function advanceStory(){const n=journeyNodes[journeyNode];if(n)showNode(n.next);}
function storyWrap(s,x,y,w,max=5){let lines=[];for(const paragraph of s.toUpperCase().split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(line&&pixelMeasure(line+' '+word,8)>w){lines.push(line);line=word;}else line+=(line?' ':'')+word;}lines.push(line);}lines.slice(0,max).forEach((line,i)=>text(line,x,y+i*10,8));}
function storyImage(key){if(key==='party'){['wanderer','knight','mage'].forEach((k,i)=>{const im=images[k];ctx.drawImage(im,0,0,im.width,im.height,42+i*79,0,78,160);});return;}const im=images[key];if(!im)return;const isIcon=['camp_wrapper','shop_leviathan'].includes(key),portrait=['wanderer','mage','knight'].includes(key);if(isIcon||portrait){const bg=images[isIcon?'shop_scene':'coast'];ctx.drawImage(bg,0,0,bg.width,bg.height,0,0,320,160);if(isIcon)ctx.drawImage(im,112,32,96,96);else ctx.drawImage(im,101,0,118,160);return;}ctx.save();ctx.beginPath();ctx.rect(0,0,320,160);ctx.clip();const ratio=Math.max(320/im.width,160/im.height),w=Math.round(im.width*ratio),h=Math.round(im.height*ratio);ctx.drawImage(im,(320-w)/2,(160-h)/2,w,h);ctx.restore();}
function drawQuestion(body,yes,no,choice=0){rect(0,0,320,240,'#000000');buttons=[];const lines=[];let line='';for(const word of body.toUpperCase().split(/\s+/)){if(line&&pixelMeasure(line+' '+word,8)>288){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);lines.forEach((l,i)=>text(l,160,88-(lines.length-1)*6+i*12,8,'#e4e6e8','center'));[['ДА',yes],['НЕТ',no]].forEach(([label,fn],i)=>{const x=64+i*106;const shown=(choice===i?'◉ ':'')+label;text(shown,x+43,137,8,choice===i?'#e5c695':'#e4e6e8','center');hit(label,x,128,86,27,fn);});}
function drawMapQuestion(){panel(56,75,208,87);const body='Вы хотите отправиться '+points[selected].destination+'?';const lines=[];let line='';for(const word of body.toUpperCase().split(/\s+/)){if(line&&pixelMeasure(line+' '+word,8)>184){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);lines.forEach((l,i)=>text(l,160,87+i*11,8,'#e4e6e8','center'));[['ДА',travel],['НЕТ',()=>{dialog=false;render()}]].forEach(([label,fn],i)=>{const x=108+i*60;rect(x,135,8,8,'#a8aeb5');rect(x+1,136,6,6,'#25313c');if(mapChoice===i)rect(x+2,137,4,4,'#dce5ed');text(label,x+12,136,8,'#e4e6e8');hit(label,x-4,128,53,24,fn);});}
function drawStory(){const n=journeyNodes[journeyNode];if(n.type==='question'){drawQuestion(n.body,()=>showNode(n.next),()=>showNode(n.no),journeyChoice);return;}rect(0,0,320,240,'#000000');storyImage(n.image);storyWrap(n.body,10,168,300,4);if(journeyNode==='intro5')text('ГЕРОИ ПОЛУОСТРОВА',160,174,8,'#e5c695','center');if(n.type==='epilogue')button('С НАЧАЛА',103,218,114,20,startJourney);else hit('Продолжить',0,0,320,240,advanceStory);}
let exchangeItem=0,exchangeWon=false,exchangeMessage='',exchangeDrag=null;
function launchExchange(){screen='exchange';dialog=false;exchangeItem=0;exchangeWon=false;exchangeMessage='Поделитесь местом для ночлега с товарищем.';controls.classList.remove('map-mode','dragging');render();}
function drawExchange(){rect(0,0,320,240,'#060d16');panel(4,3,312,18);text('СТРАННИК НА ПЕРЕВАЛЕ',160,9,8,'#e5c695','center');panel(4,24,190,136);ctx.drawImage(images.shore_north,8,28,182,128);ctx.drawImage(images.wanderer,65,30,66,125);panel(199,24,117,188);storyWrap('Что ты можешь предложить страннику?',207,34,101,5);['shop_tin','shop_mug','camp_tent'].forEach((a,i)=>{const x=202+i*36;panel(x,113,32,32,'ui_button');if(exchangeItem===i)rect(x+4,117,24,24,'#2b4059');ctx.drawImage(images[a],x+3,116,26,26);hit(['Еда','Кружка','Место в палатке'][i],x,113,32,32,()=>{exchangeItem=i;render();});});button('ОБМЕНЯТЬ',203,171,109,23,exchangeOffer);panel(4,163,190,49);storyWrap(exchangeWon?'Странник разделит с вами место для ночлега.':exchangeMessage,12,173,174,4);panel(4,215,312,24);storyWrap(exchangeWon?'Вы делитесь тесной кельей с товарищем.':'Выберите предмет справа и предложите обмен.',12,220,296,1);if(exchangeWon){rect(4,24,312,188,'#050a12bb');panel(30,65,260,100);text('ОБМЕН СОСТОЯЛСЯ',160,80,8,'#e5c695','center');buttons=[];hit('Продолжить',0,0,320,240,gameCompleted);}}
function exchangeOffer(){if(exchangeItem===2){exchangeWon=true;announce('Вы поделились местом для ночлега.');render();}else{exchangeMessage='Страннику нужно место для ночлега. Предложите место в палатке.';announce(exchangeMessage);render();}}
function journeyKey(e){if(!['Enter',' ','Escape','ArrowLeft','ArrowRight','1','2','3'].includes(e.key))return;e.preventDefault();if(e.repeat)return;if(e.key==='Escape'){journeyActive=false;showNode('map');return;}if(screen==='question'){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){journeyChoice=1-journeyChoice;render();}else if(e.key==='Enter'||e.key===' ')showNode(journeyChoice?journeyNodes[journeyNode].no:journeyNodes[journeyNode].next);}else if(screen==='exchange'){if(['1','2','3'].includes(e.key)){exchangeItem=Number(e.key)-1;render();}if(e.key==='Enter'||e.key===' '){if(exchangeWon)gameCompleted();else exchangeOffer();}}else if(e.key==='Enter'||e.key===' '){if(screen==='epilogue')startJourney();else advanceStory();}}
controls.addEventListener('pointerdown',e=>{if(screen!=='exchange'||exchangeWon||e.button!==0)return;const p=mapPointer(e);if(p.y>=176&&p.y<204&&p.x>=198&&p.x<285){exchangeItem=Math.floor((p.x-198)/29);exchangeDrag=e.pointerId;controls.setPointerCapture(e.pointerId);render();}});
controls.addEventListener('pointerup',e=>{if(screen!=='exchange'||exchangeDrag!==e.pointerId)return;exchangeDrag=null;const p=mapPointer(e);if(p.x<197&&p.y>=22&&p.y<160)exchangeOffer();if(controls.hasPointerCapture(e.pointerId))controls.releasePointerCapture(e.pointerId);});
controls.addEventListener('pointercancel',()=>exchangeDrag=null);
document.querySelector('#demo-start').onclick=startJourney;


// Current Figma screens own the presentation; existing engines own game rules.
function text(s,x,y,size=8,color='#e4e6e8',align='left'){currentUI.text(ctx,currentUI.case(s),x,y,align)}
function panel(x,y,w,h,asset='ui_frame'){currentUI.box(ctx,x,y,w,h,asset==='ui_button'?'#635443':'#293640');if(w>=160&&h>=60&&x>15){ctx.drawImage(currentUI.stone,0,0,w,h,x,y,w,h);ctx.strokeStyle='#91a1ad';ctx.strokeRect(x+.5,y+.5,w-1,h-1)}}
function drawTitle(){currentUI.base(ctx,'title');hit('Начать игру',0,0,320,240,startJourney)}
function drawHero(){currentUI.base(ctx,'hero'+hero);hit('Предыдущий герой',7,213,62,21,()=>changeHero(-1));hit('Случайный герой',70,213,62,21,()=>{hero=(hero+1+Math.floor(Math.random()*2))%3;render()});hit('Следующий герой',133,213,64,21,()=>changeHero(1));hit('Карта',198,213,115,21,()=>{if(journeyStarted)showNode('intro5');else setScreen('map')})}
function drawMap(){rect(0,0,320,240,'#11171c');clampCamera();ctx.save();ctx.beginPath();ctx.rect(mapView.x,mapView.y,mapView.w,mapView.h);ctx.clip();ctx.drawImage(images.map,mapView.x-camera.x,mapView.y-camera.y);for(let i=0;i<points.length;i++){const p=points[i],x=p.x-camera.x+mapView.x,y=p.y-camera.y+mapView.y;if(x<5||x>315||y<27||y>207)continue;rect(x-3,y-3,7,7,'#000');rect(x-2,y-2,5,5,visited.has(i)?'#84b5a7':i===selected?'#f1d39a':'#d7b574');hit(p.full,x-6,y-6,13,13,()=>selectDestination(i));buttons[buttons.length-1].mapPoint=true}ctx.restore();currentUI.header(ctx,'Курский полуостров');rect(0,212,320,28,'#11171c');rect(0,212,320,1,currentUI.settings.lineColor);currentUI.roleBlock(ctx,'Выбери локацию',1,217,318,22,'mapFooter');if(dialog)drawMapQuestion();if(loading){buttons=[];PeninsulaPopup.draw(ctx,{title:'В пути',body:points[selected].full,labels:[]});const p=PeninsulaPopup.last;rect(p.x+10,p.y+p.h-20,p.w-20,6,'#11171c');rect(p.x+10,p.y+p.h-20,Math.round((p.w-20)*progress),6,'#d7b574')}}
function questionHits(yes,no,choice=0){[['ДА',yes],['НЕТ',no]].forEach(([label,fn],i)=>{const x=90+i*80;if(choice===i){ctx.strokeStyle='#e5c695';ctx.strokeRect(x+.5,142.5,59,15)}hit(label,x,142,60,16,fn)})}
function drawMapQuestion(){buttons=[];const actions=[travel,()=>{dialog=false;render()}];PeninsulaPopup.draw(ctx,{body:'Вы хотите отправиться '+points[selected].destination+'?',labels:['Да','Нет'],choice:mapChoice}).forEach((b,i)=>hit(b.label,b.x,b.y,b.w,b.h,actions[i]));}
function beginChapter(i){journeyActive=true;selected=i;const id='q'+i;journeyNodes[id]={type:'question',body:chapterQuestions[i],next:(i+1)+'.1',no:i===3?'4.1':'map'};showNode(id)}
function drawQuestion(body,yes,no,choice=0){const chapter=/^q[0-4]$/.test(journeyNode)?String(Number(journeyNode.at(-1))+1):journeyNode==='ruin'?'2':journeyNode==='home'?'5':'1';currentUI.base(ctx,chapter+'.1');buttons=[];PeninsulaPopup.draw(ctx,{body,labels:['Да','Нет'],choice}).forEach((b,i)=>hit(b.label,b.x,b.y,b.w,b.h,i?no:yes))}
function drawStory(){const n=journeyNodes[journeyNode];if(n.type==='question'){drawQuestion(n.body,()=>showNode(n.next),()=>showNode(n.no),journeyChoice);return;}const k=currentUI.images[journeyNode]?journeyNode:'win5';currentUI.base(ctx,k);hit('Продолжить',0,0,320,240,n.type==='epilogue'?startJourney:advanceStory)}
let exchangeCategory=0;
function drawExchange(){currentUI.base(ctx,'exchange4');const cats=['ОБМЕН','ВЕЩИ','ЕДА','СНАРЯЖ.'];cats.forEach((name,i)=>hit(name,198+(i%2)*58,40+Math.floor(i/2)*17,57,16,()=>{exchangeCategory=i;render()}));const offers=exchangeCategory===0?[0,1,2]:exchangeCategory===1?[1]:exchangeCategory===2?[0]:[2];offers.forEach((i,j)=>{const x=198+(j%4)*29,y=74+Math.floor(j/4)*29;ctx.drawImage(images[['shop_tin','shop_mug','camp_tent'][i]],x+2,y+2,24,24);hit(['Еда','Кружка','Место в палатке'][i],x,y,28,28,()=>{exchangeItem=i;exchangeOffer()})});rect(12,166,178,62,'#11171c');currentUI.roleBlock(ctx,exchangeMessage.replace(/(?<=[.!?])\s+/g,'\n'),8,166,188,66,'dialogue');currentUI.bag(ctx,['shop_tin','shop_mug','camp_tent'],images);if(exchangeWon){const b=currentUI.modal(ctx,'Обмен состоялся','Вы делитесь местом для ночлега с товарищем.');buttons=[];hit(b.label,b.x,b.y,b.w,b.h,gameCompleted)}}
const drivingScene=document.createElement('canvas');drivingScene.width=320;drivingScene.height=240;
function drivingPresentation(d,mode){
 currentUI.base(ctx,mode==='home'?'traffic5':'fog4');
 currentUI.clip(ctx,8,23,304,136,()=>ctx.drawImage(drivingScene,0,0,320,240,8,23,304,136));
 currentUI.header(ctx,mode==='home'?'Дорога домой':'Перевал Геологов');currentUI.resource(ctx,'Топливо',Math.max(0,Math.round(100-d.progress*70))+'%');currentUI.slots(ctx);
 rect(8,162,188,71,'#11171c');currentUI.box(ctx,7,161,190,72,'#11171c');
 currentUI.block(ctx,d.warning?'Осторожно, край обрыва.\nСбавь скорость.':mode==='home'?'Поток стоит. Ищите свободный путь домой.':'Туман густеет. Держитесь дороги и подавайте сигнал.',8,166,188,66);
 if(d.state==='title'||d.state==='over')currentUI.modal(ctx,d.state==='title'?mode==='home'?'Дорога домой':'Перевал Геологов':'Попробуйте ещё',d.state==='title'?'Стрелки — управление. Нажмите на экран, чтобы поехать.':d.msg?.t1||'Машина повреждена.');
}
function launchFogRace(mode='fog'){screen='fog';dialog=false;controls.replaceChildren();controls.classList.remove('map-mode','dragging');drivingGames[mode]?.stop();drivingGames[mode]=window.createFogRace({canvas:drivingScene,inputSurface:controls,drawPanel:panel,mode,background:images.coast,demoFinish:journeyActive,compactUI:true,onRender:d=>drivingPresentation(d,mode),onComplete:()=>{if(journeyActive)gameCompleted();else launchCampSearch()}});fogGame=drivingGames[mode];fogGame.start();render()}
